mapper.select:
SELECT item_id, name, category, sub_type, color, pattern, seasons, styles, formality, status, brand,
       worn_count, last_worn_at, created_at
  FROM tb_wardrobe_item
 WHERE user_id = #{userId}

   AND category = #{category}


   AND status = #{status}


   AND color = #{color}



   AND (name ILIKE #{queryPattern} ESCAPE '\' OR brand ILIKE #{queryPattern} ESCAPE '\')



 ORDER BY worn_count DESC, last_worn_at DESC NULLS LAST, item_id DESC



 ORDER BY lower(name) COLLATE "C" ASC, item_id ASC


 ORDER BY created_at DESC, item_id DESC

SELECT count(*)
  FROM tb_wardrobe_item
 WHERE user_id = #{userId}
   AND last_worn_at >= #{since}

SELECT item_id
  FROM tb_wardrobe_item
 WHERE user_id = #{userId}
   AND (last_worn_at IS NULL OR last_worn_at < #{before})
 ORDER BY last_worn_at ASC NULLS FIRST, created_at ASC, item_id ASC
 LIMIT #{limit}

SELECT count(*)
  FROM tb_wardrobe_item

    WHERE category = #{code}
    WHERE sub_type = #{code}
    WHERE color = #{code}
    WHERE pattern = #{code}
    WHERE status = #{code}
    WHERE #{code} = ANY (seasons)
    WHERE #{code} = ANY (styles)
    WHERE FALSE
